pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 times) public {
        // Bound amount to TICKET_AMOUNT (10) and times to a reasonable number
        vm.assume(amount == 10);
        vm.assume(times > 0 && times <= 10);

        uint256 initialPot = 0;

        for (uint256 i = 0; i < times; i++) {
            // Each call increments pot by msg.value = amount
            // After a win (random == 0), pot is set to 0
            // After a loss (random == 1), pot stays incremented
            c.play{value: amount}();
        }

        // The general rule: pot cannot exceed the total value sent (amount * times)
        assertTrue(c.pot() <= amount * times);
    }
}

