pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialPot) public {
        uint256 potBefore = c.pot();
        vm.assume(initialPot <= type(uint256).max - 10); // avoid overflow when adding ticket amount

        // Set an arbitrary initial pot (simulate prior calls)
        // We cannot set pot directly, so we simulate by calling play() multiple times
        // Instead, we'll just use the current pot and check invariants across a single play()

        c.play{value: 10}();

        uint256 potAfter = c.pot();

        // The rule: After a play(), the pot is either:
        // - 0 (if player won and bank took fee) 
        // - previousPot + 10 (if player lost, pot accumulates ticket amount)
        // The bug (pot = 0) breaks this: after a loss, pot would be 0 instead of previousPot + 10
        bool valid = (potAfter == 0) || (potAfter == potBefore + 10);
        assertTrue(valid, "Pot not in expected state after play()");
    }
}

