pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount == 10);
        vm.deal(caller, amount);
        vm.prank(caller);
        vm.assume(amount == c.TICKET_AMOUNT());
        uint potBefore = c.pot();
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));
        if (success) {
            uint potAfter = c.pot();
            // If the call reverted, we cannot say anything about pot.
            // But if it succeeded, then either the caller lost (random == 0) => pot becomes 0, or won => pot unchanged.
            // Actually, if random == 0, pot becomes 0. If random == 1, pot stays same (the msg.value is added by reference but not by mutant).
            // In reference C, potAfter = (random == 0) ? 0 : potBefore + 10;
            // In mutant M, potAfter = (random == 0) ? 0 : potBefore;
            // So the difference: after a win (random == 1), reference's pot increases by 10, mutant's stays same.
            // But we cannot observe random externally. Instead, we can say: after a successful play(), the pot is either 0 (if lost) or (potBefore + 10) (if won) in reference.
            // Thus potAfter is always either 0 or potBefore + 10.
            assertTrue(potAfter == 0 || potAfter == potBefore + 10);
        }
    }
}

