pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value == 10); // TICKET_AMOUNT
        uint256 balanceBefore = address(c).balance;
        c.play{value: value}();
        uint256 balanceAfter = address(c).balance;
        // The rule: after play(), if the random was 0, the fee should have been transferred to bank
        // but the bank's balance is not observable. Instead: the contract balance should be exactly
        // the amount that would remain after transferring the fee to bank.
        // When random == 0, the reference sends 1 wei to bank, then sends pot-1 to player, pot=0.
        // So contract balance after = (previous balance + 10) - 1 - (pot-1) = previous balance + 10 - pot.
        // pot ends at 0, so balanceAfter = balanceBefore + 10 - (potBefore + 10?) Not simple.
        // Actually we need a rule that holds on reference but fails on mutant.
        // Mutant omits the transfer to bank, so contract retains the fee.
        // Rule: let initialPot = pot before play; after play, if we did not revert,
        // then (pot == 0) implies address(c).balance == balanceBefore + value - (potBefore + value) ???
        // Simpler: The invariant for reference: after play, contract balance is divisible by 1? No.
        // The reference always sends fee to bank when random==0, so contract balance always ends as a multiple of 10? Let's analyze:
        // Reference: when random==0, contract sends 1 to bank, sends pot-1 to player, pot=0.
        // So contract loses (1 + (pot-1)) = pot wei from its balance. Since pot before was balanceBefore + 10? No, pot is separate.
        // Actually pot accumulates from ticket amounts. In reference, after a win, contract retains 0 (all sent out).
        // In mutant, after win, contract retains the fee (1 wei) because it doesn't send to bank.
        // So the rule: after play() with value == 10, if no revert, then address(c).balance == 0 always in reference.
        // Because contract starts with 0, each play either loses (random==1) adding 10 to pot, or wins (random==0) sending everything out.
        // But after a loss, pot=10, contract balance=10. The rule fails then.
        // So need to account for pot: After any call to play(), the contract balance equals pot.
        // Is that true? Reference: after loss (random==1), pot=10, contract balance=10 (value added, no outgoing). True.
        // After win (random==0), pot=0, contract balance=0 (all sent out). True.
        // Mutant: after win, contract balance = 1 (fee kept) but pot = 0. So invariant broken.
        // Let's assert: address(c).balance == c.pot()
        assertTrue(address(c).balance == c.pot());
    }
}

